test('late synthetic continuation preparation cannot attach after cancellation, abandonment, navigation, sign-out or unmount',async()=>{
 const f=await replayContextFixture(),trial={...f.selected,origin:'SYNTHETIC_OFFLINE',source:null},offlineContext=await replayForward.createReplayForwardContext([trial],trial.localId);
 for(const action of ['cancel','abandon','navigate','logout','unmount']){
  server();const h=harness({signedIn:true});await h.until('No visible public definitions');replayContextFile(h,offlineContext);await h.until('Synthetic replay context imported locally');
  const held=context.refs.find(ref=>ref.current?.attempts);let release;globalThis.__syntheticPrepareOverride=(...args)=>{const actual=args.pop();return new Promise(resolve=>release=async()=>{const value=await actual(...args);resolve(value);return value;});};
  h.click('Prepare synthetic continuation');await h.until(()=>typeof release==='function');
  if(action==='cancel')h.click('Cancel local confirmation');if(action==='abandon'){h.click('Cancel local confirmation');await h.flush();h.click('Abandon replay association');}if(action==='navigate')h.navigate('?invalid=1');if(action==='logout'){h.props.signedIn=false;await h.flush();}if(action==='unmount')h.unmount();
  await release();await h.flush();assert.equal(held.current.example,null);assert.equal(held.current.activeId,null);assert.equal(held.current.attempts.length,0);assert.equal(exports.length,0);
 }
});

