  let release;globalThis.__sessionSnapshotOverride=(...args)=>{const actual=args.pop();return new Promise(resolve=>release=async()=>{const value=await actual(...args);resolve(value);return value;});};
  h.click('Export synthetic journey report');await h.until(()=>typeof release==='function');
  if(action==='cancel')h.click('Cancel local confirmation');if(action==='abandon'){h.click('Cancel local confirmation');await h.flush();h.click('Abandon replay association');}if(action==='navigate')h.navigate('?invalid=1');if(action==='logout'){h.props.signedIn=false;await h.flush();}if(action==='unmount')h.unmount();
