test('a publication-size rejection keeps the exact complete local checkpoint without trimming, export or posting',async()=>{
 // The core suite checks the real full-input byte boundary; this fixture injects that typed
 // failure at the actual UI helper boundary instead of repeating a 700-event stress replay.
 const value=await opened('DCA','PUBLIC_STRATEGY'),{requests}=server([value.source]),h=harness();await h.until(value.source.record.content.name);await restored(h,value.journal);await reviewFields(h);let calls=0;globalThis.__sessionSnapshotOverride=(raw)=>{calls++;assert.deepEqual(raw,value.journal);const error=new Error('Synthetic core size-rejection fixture');error.status=413;throw error;};h.click('Export review bundle');await h.until('Review bundle not exported');const held=context.refs.find(r=>r.current?.attempts).current;assert.equal(calls,1);assert.deepEqual(held.attempts[0].journal,value.journal);assert.equal(exports.length,0);assert(text(h.render()).includes('events are never trimmed to fit'));assert(!requests.some(r=>r.init.method==='POST'));
});
